const AdmZip = require('/tmp/node_modules/adm-zip');
const zip = new AdmZip('/workspace/testbed/docs/customer_report.docx');
const xml = zip.readAsText('word/document.xml');

// Strip XML tags and extract text content
const text = xml
  .replace(/<w:tab\/>/g, '\t')
  .replace(/<w:br\/>/g, '\n')
  .replace(/<\/w:p>/g, '\n')
  .replace(/<[^>]+>/g, '')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '\"')
  .replace(/&apos;/g, \"'\")
  .replace(/\n{3,}/g, '\n\n')
  .trim();

console.log(text);
